function MournTowerDialog:OnFocus(focus)
	if focus then
		local currency = ActivityMournUtils.GetShowCurrency()
		if table.count(currency) > 0 then
			CfUtils.RefreshTopGoods(currency)
		end
	end
end

function MournTowerDialog:OnShow()
	--- @type Engine.Lib.CoWait
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		if not self.isInit then
			CfUtils.PlayAnimator(self.controller, "Go")
			self.isInit = true
		else
			CfUtils.PlayAnimator(self.controller, "Default")
		end
		
		local lastId = KCookie.Get("MournTowerQuestId")
		if checkNumber(lastId) > 0 then
			local vo = QuestConfMgr:GetInstance():GetQuestVoById(lastId)
			local activityVo = ActivityMournUtils.GetSchConfig()
			
			--最大 不播
			if checkNumber(vo.storey) == checkNumber(activityVo.layers) then
				return
			end
			
			KCookie.Set("MournTowerQuestId", 0)
			self._co = cs_coroutine.start(function()
				UIRaycastBlocker:AddCondition("MournTowerDialog")
				self:InitData()
				CfUtils.PlayAnimator(self.controller, "Switch")
				coroutine.yield(CS.UnityEngine.WaitForSeconds(0.33))
				
				self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
				self:FillSelf()
				
				coroutine.yield(CS.UnityEngine.WaitForSeconds(0.783))
				UIRaycastBlocker:RemoveCondition("MournTowerDialog")
			end)
		end
	end))
	return coWait
end

function MournTowerDialog:OnBattleLoadedOverHandler()
	CfUtils.StartCoroutineWithBlocker(function()
		xTry(function()
			local nowQuestId = checkNumber(self._curQuestId)
			self._curQuestId = checkNumber(self._curQuestId) - 1
			self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
			if isNull(self._curQuestVo) then
				goto start
			end
			self:FillSelf()
			
			cs_coroutine.yield_return(WaitForSeconds(0.8))
			CfUtils.PlayAnimator(self.controller, "Switch")
			cs_coroutine.yield_return(WaitForSeconds(0.5))
			
			::start::
			
			self._curQuestId = nowQuestId
			self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
			self:FillSelf()
		end)
	end)
end

function MournTowerDialog:Awake()
	self.events[Constants.EventNames.ExitBattleLoadOver] = Events.AddListener(Constants.EventNames.ExitBattleLoadOver, Bind(self, self.OnBattleLoadedOverHandler))
	CfUtils.SetActive(self.BtnEasyWay, false)
	ActivityMournUtils.PlayBgm()
	self.events[Constants.EventNames.ActivityNightCatResetRecover] = Events.AddListener(Constants.EventNames.ActivityNightCatResetRecover, Bind(self, self.FillResetInfo))
	SetButtonAction(self.BtnEasyWay, Bind(self, self.OnBtnEasyWay))
	SetButtonAction(self.BtnReward, Bind(self, self.OnBtnReward))
	SetButtonAction(self.BtnBuff, Bind(self, self.OnBtnBuff))
	SetButtonAction(self.BtnFight, Bind(self, self.OnBtnFight))
	SetButtonAction(self.BtnSet, Bind(self, self.OnBtnRefresh))
	SetButtonAction(self.ImgTime, function()
		UICommonUtils.ShowAttributeTips(self.ImgTime, {
			nightCat = true,
			name = localize("每次重置均会延长关卡的重置时间。"),
			descr = localize("第1~3次：15分钟\n第4~6次：30分钟\n第7~9次：1小时\n第10~12次：2小时\n第13次及以上：8小时\n每日5点将会重置累计次数。"),
		})
	end)
	
	self.activityData = ActivityMournUtils.GetActivityData()
	self._activityId = self.activityData.activityContentId
	
	self:InitData()
	self:RefreshUpGroup()
	self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
	if not self._curQuestVo then
		return
	end
	
	self:FillSelf()
end

function MournTowerDialog:RefreshUpGroup()
	local upGroup = ActivityMournUtils.GetUpGroup()
	UICommonUtils.RefreshCommonUpGroup(self.CommRoleBonusLayoutGroup, upGroup, true,{{id = Constants.UITypeIds.MournTowerDialog}})
end

function MournTowerDialog:RefreshResetTime()
	self:RemoveReSetTimer()
	local curTime = GameUtils.GetServerTime() or os.time()
	if self._homeDojo and self._homeDojo.nextHpSeconds - curTime >= 0 and self._homeDojo.climbingResetNum < self._homeDojo.limit then
		local leftSeconds = self._homeDojo.nextHpSeconds - curTime
		CfUtils.FillText(self.TxtTimeNumber, CfUtils.GetTimeHMS2(leftSeconds))
		self.resetTimer = CDTimerModule.GetInstance():AddCD(1, function(countTimes, timerId)
			if countTimes <= 0 then
				self:RemoveReSetTimer()
				CfUtils.FillText(self.TxtTimeNumber, CfUtils.GetTimeHMS2(0))
			else
				CfUtils.FillText(self.TxtTimeNumber, CfUtils.GetTimeHMS2(countTimes))
			end
		end, leftSeconds, true, true)
	end
end

function MournTowerDialog:RemoveReSetTimer()
	if self.resetTimer then
		CDTimerModule.GetInstance():RemoveCD(self.resetTimer)
		self.resetTimer = nil
	end
end

function MournTowerDialog:InitData()
	local id = ActivityMournUtils.GetCurPassTowerId()
	local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
	if not vo then
		local t = ActivityMournUtils.GetTowerLevelVos(self._activityId)
		self._curQuestId = t[1].id
		return
	end
	
	--通关了
	if checkNumber(vo.nextLevel) == 0 then
		self._curQuestId = id
	else
		self._curQuestId = vo.nextLevel
	end
	
	local lastId = KCookie.Get("MournTowerQuestId")
	if checkNumber(lastId) > 0 then
		self._curQuestId = lastId
	end
end

function MournTowerDialog:FillSelf()
	self:FillRewards()
	
	local num = checkNumber(self._curQuestVo.storey)
	CfUtils.SetActive(self.ImgNumber22, num >= 10)
	
	CfUtils.SetActive(self.ImgNumber11, num >= 100)
	
	CfUtils.SetUISwitchImage(self.ImgNumber33, num % 10 + 1)
	
	local num1 = math.floor(num / 10)
	CfUtils.SetUISwitchImage(self.ImgNumber22, num1 % 10 + 1)
	
	num1 = math.floor(num1 / 10)
	CfUtils.SetUISwitchImage(self.ImgNumber11, num1 % 10 + 1)
	
	local isPassAll = ActivityMournUtils.IsMournPassAll(self._activityId)
	self.ImgNumber11.transform:GetComponent(UIGrayGraphics):MarkGray(isPassAll)
	self.ImgNumber22.transform:GetComponent(UIGrayGraphics):MarkGray(isPassAll)
	self.ImgNumber33.transform:GetComponent(UIGrayGraphics):MarkGray(isPassAll)
	
	local isFinish = false
	local vo = ActivityMournUtils.GetSchConfig()
	if vo then
		local maxTowerId = ActivityMournUtils.GetMaxPassTowerId()
		if maxTowerId == 0 then
			CfUtils.FillText(self.TxtNumber, "0/"..vo.layers)
		else
			local questVo = QuestConfMgr:GetInstance():GetQuestVoById(maxTowerId)
			CfUtils.FillText(self.TxtNumber, (checkNumber(questVo.storey)).."/"..vo.layers)
		end
		
		local curId = ActivityMournUtils.GetCurPassTowerId()
		local curVo = QuestConfMgr:GetInstance():GetQuestVoById(curId)
		if curVo then
			isFinish = (checkNumber(curVo.storey) == checkNumber(vo.layers))
		end
	end
	
	local monsterVo = CardConfMgr:GetInstance():GetBaseMonstVo(self._curQuestVo.showMonster)
	if isNotNull(monsterVo) then
		local vo = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", monsterVo.skinId)
		if isNotNull(vo) then
			CfUtils.FillImage(self.ImgActionHead,vo.cardDrawing)
		end
	end
	
	CfUtils.SetActive(self.ClearanceNode, isFinish)
	CfUtils.SetActive(self.BtnFight, not isFinish)
	self:FillResetInfo()
	self:RefreshBtnEasyWay()
end

function MournTowerDialog:OnBtnEasyWay()
	if isNull(self.targetLevelId) then
		return
	end

	GameUtils.Request(Interfaces.ActivityTowerChangeTowerFastClimb,{activityUuid = self.activityData.id},function(request,response)
		if checkNumber(response.errCode) == 0 then
			local jsonData = checkTable(response.data)
			if #jsonData.rewards > 0 then
				GoodsUtils.DrawRewards(jsonData.rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards } })
			end
			self._homeDojo:UpdateCurTowerId(jsonData.climbingNowFloor)
			CS.Engine.Lib.KCookie.Set("MournTowerQuestId", jsonData.climbingNowFloor)
			self:OnShow()
		end
	end)
end

function MournTowerDialog:RefreshBtnEasyWay()
	---@TODO
	CfUtils.SetActive(self.BtnEasyWay, false)
	local maxId = ActivityMournUtils.GetMaxPassTowerId()
	
	local refLevel = 5
	
	--- 历史最高层数和当前层数相差大于5层 就显示按钮
	---@type NightCatTowerQuestVo
	local maxVo = QuestConfMgr:GetInstance():GetQuestVoById(maxId)
	if isNull(maxVo) then
		return
	end
	
	--- 当前层数如果超过目标层数则不显示
	local curPassId = ActivityMournUtils.GetCurPassTowerId()
	local curVo
	local curLevel = 0
	if curPassId ~= 0 then
		curVo = QuestConfMgr:GetInstance():GetQuestVoById(curPassId)
		curLevel = curVo.storey
	end
	
	local targetLevel = maxVo.storey - curLevel
	if targetLevel > refLevel then
		self.targetLevelId = maxId - refLevel
		CfUtils.SetActive(self.BtnEasyWay, true)
	end
end

--重置
function MournTowerDialog:FillResetInfo()
	self._homeDojo = ActivityMournUtils.GetHomeDojo()
	CfUtils.FillText(self.TxtTime, localize("剩余重置次数：<color=#ff4777>_count1_</color>/_count2_", {_count1_=self._homeDojo.climbingResetNum, _count2_=self._homeDojo.limit}))
	
	self:RefreshResetTime()
	local isHaveResetNum = self._homeDojo.climbingResetNum > 0
	--没次数了
	if not isHaveResetNum or ActivityMournUtils.GetCurPassTowerId() == 0 then
		self.BtnSet.transform:Find("ImgTxtBg").transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(true)
		return
	end
	
	CfUtils.SetActive(self.BtnSet.transform:Find("TxtFight"), isHaveResetNum)
	
	self.BtnSet.transform:Find("ImgTxtBg").transform:GetComponent(typeof(CS.Engine.UI.UIGrayGraphics)):MarkGray(not isHaveResetNum)

	
end

--开始倒计时
function MournTowerDialog:StartTimeDown()
	if not isNull(self._timeDown) then
		CDTimerModule.GetInstance():RemoveCD(self._timeDown)
		self._timeDown = nil
	end
	
	self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
		local time = comp:GetClimbingResetTtl()
		if checkNumber(time) <= 0 then
			self:FillResetInfo()
		else
			CfUtils.FillText(self.TxtTimeNumber, CfUtils.GetTimeHMS2(time))
		end
	end, CountDownTime, false, true)
end

function MournTowerDialog:FillRewards()
	local t = RewardConfMgr:GetInstance():GetTeamShowRewardData(self._curQuestId)
	if not t then
		return
	end
	
	for i = 1, self.RewardList.childCount do
		local go = self.RewardList:GetChild(i - 1)
		if go then
			CfUtils.SetActive(go, false)
		end
	end
	
	for k, v in pairs(t) do
		local go = self.RewardList.transform:Find("Good"..k)
		if not go then
			go = CfUtils.InstantiateGo(self.Good, self.RewardList)
			go.name = "Good"..k
		end
		
		self:FillReward(go, v)
	end
end

function MournTowerDialog:FillReward(go, data)
	if not go or not data then
		return
	end
	CfUtils.RefeshGoodGo(go.transform:Find("GoodNode"), data.id, data.num, 0.65, nil, function()
		local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.id)
		if vo then
			GameUtils.ShowCommonTipsBoard(go.transform:Find("TipRoot"), vo.name, nil, vo.quality, data.id, false,nil)
		end
	end)
	CfUtils.FillRewardGoTitle(go.transform:Find("GoodNode"), data)
	CfUtils.SetActive(go, true)
	
	--必定掉落不灰
	local type = checkNumber(data.type)
	if type == Constants.TeamShowRewardType.RegularType then
		return
	end
	
	local maxTowerId = ActivityMournUtils.GetMaxPassTowerId()
	local maxVo = QuestConfMgr:GetInstance():GetQuestVoById(maxTowerId)
	if maxVo then
		local scr = CfUtils.GetLuaScr(go.transform:Find("GoodNode"), "Game.Behaviours.GoodNodeMB")
		if scr then
			scr:SetSanXingGainShow(checkNumber(maxVo.storey) >= checkNumber(self._curQuestVo.storey))
		end
	end
end

function MournTowerDialog:OnBtnRefresh()
	local isEnd = ActivityMournUtils.IsActivityEnd(true)
	if isEnd then
		return
	end
	local questId = ActivityMournUtils.GetCurPassTowerId()
	if isNull(self._homeDojo) or questId == 0 then
		GameUtils.Toast(localize("请先通关一层关卡后再尝试"))
		return
	end
	local isHaveResetNum = self._homeDojo.climbingResetNum > 0
	if not isHaveResetNum then
		GameUtils.Toast(localize("重置次数不足"))
		return
	end
	
	GameUtils.SecondConfirm(localize("是否要重置"), function()
		GameUtils.Request(Interfaces.ActivityTowerChangeTowerReset,{activityUuid = self.activityData.id},function(request, response)
			if checkNumber(response.errCode) == 0 then
				self._homeDojo:UpdateCurTowerId(0)
				self._co = cs_coroutine.start(function()
					UIRaycastBlocker:AddCondition("MournTowerDialog")
					self._homeDojo:RefreshResetInfo(response.data)
					ActivityMournUtils.StartTimeDown()
					CfUtils.PlayAnimator(self.controller, "Switch")
					coroutine.yield(CS.UnityEngine.WaitForSeconds(0.2))
					self:InitData()
					self._curQuestVo = QuestConfMgr:GetInstance():GetQuestVoById(self._curQuestId)
					self:FillSelf()
					coroutine.yield(CS.UnityEngine.WaitForSeconds(1.083 - 0.2))
					UIRaycastBlocker:RemoveCondition("MournTowerDialog")
				end)
			end
		end)
	end, function()
	
	end)
end

function MournTowerDialog:OnBtnFight()
	local isEnd = ActivityMournUtils.IsActivityEnd(true)
	if isEnd then
		return
	end
	
	local isPassAll =  ActivityMournUtils.IsPallAllQuest()
	if isPassAll then
		GameUtils.Toast(localize("已通关全部"))
		return
	end
	local activityData = ActivityMournUtils.GetActivityData()
	UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self._curQuestId, upBuffData = self:GetUpBuffData(), activityUuid = activityData.id } }, {
		{ id = Constants.UITypeIds.MournTowerDialog },
	})
end

function MournTowerDialog:GetUpBuffData()
	local data = {}
	local upGroup = ActivityMournUtils.GetUpGroup()
	for i, v in ipairs(upGroup) do
		local hasCard = cardComp:IsHasCard(v.refId)
		local tempData = {}
		tempData.refId = v.refId
		tempData.type = v.type
		local index = 1
		if hasCard then
			local cardDojo = cardComp:GetCardByConfId(v.refId)
			local star = cardDojo.star
			index = star + 1
		
		end
		tempData.commonAddId = v.additions[index].commonAddId
		table.insert(data,tempData)
	end
	return data
end

