function MournTowerDialog:IsHaveNewBuff()
	local t = checkTable(comp._redPointList)
	for k, v in pairs(t) do
		if checkNumber(v) == 1 then
			return true
		end
	end
	return false
end

function MournTowerDialog:OnInitialize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		local redGo = GameUtils.GetRedPointGo(self.BtnBuff)
		if redGo then
			CfUtils.SetActive(redGo, self:IsHaveNewBuff())
		end
	end))
	return coWait
end

function MournTowerDialog:OnFinalize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		if not isNull(self._behaviourAction) then
			self._behaviourAction.UpdateAction = nil
		end
		if not isNull(self._timeDown) then
			CDTimerModule.GetInstance():RemoveCD(self._timeDown)
			self._timeDown = nil
		end
		if self._co then
			cs_coroutine.stop(self._co)
			self._co = nil
		end
		if self._backCo then
			cs_coroutine.stop(self._backCo)
			self._backCo = nil
		end
		
		for k, v in pairs(self.events) do
			Events.RemoveListener(k, v)
		end
		
		self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
		self:Delete()
		self = nil --lua层的gc需要
	end))
	return coWait
end

return MournTowerDialog